
CREATE ROLE authenticated; CREATE ROLE anon; CREATE ROLE service_role; CREATE ROLE partner IN ROLE authenticated;
CREATE SCHEMA auth; CREATE SCHEMA cron;
CREATE TABLE auth.users(id uuid PRIMARY KEY, email text);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql STABLE AS $$ SELECT coalesce(nullif(current_setting('request.jwt.claim.role',true),''),'service_role') $$;
CREATE TABLE public.user_permissions(user_id uuid,permission text);
CREATE FUNCTION public.is_backoffice_admin() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT 1 FROM public.user_permissions WHERE user_id=auth.uid() AND permission='Controle de usuários') $$;
CREATE TABLE auth.sessions(id uuid DEFAULT gen_random_uuid(),user_id uuid,created_at timestamptz,refreshed_at timestamp);
CREATE TABLE public.user_profiles(id uuid PRIMARY KEY,full_name text,created_at timestamptz DEFAULT now(),isdependent boolean DEFAULT false,parent_user_id uuid);
CREATE TABLE public.chat_messages(id uuid DEFAULT gen_random_uuid(),user_id uuid,sender text,content text,workflow text,created_at timestamptz DEFAULT now());
CREATE TABLE public.engagement_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id text,event_type text,entity_type text,entity_id uuid,unified_opportunity_id text,destination_url text,source text,event_count int DEFAULT 1,user_id uuid,anonymous_id text,occurred_at timestamptz DEFAULT now(),created_at timestamptz DEFAULT now());
CREATE TABLE public.student_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid,partner_id uuid,status text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),UNIQUE(user_id,partner_id));
CREATE TABLE public.user_opportunity_matches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),profile_id uuid,unified_opportunity_id text,match_score numeric,generated_at timestamptz DEFAULT now());
CREATE TABLE public.institutions(id uuid PRIMARY KEY,name text,is_partner boolean DEFAULT true);
CREATE TABLE public.partner_opportunities(id uuid PRIMARY KEY,institution_id uuid,name text);
CREATE TABLE public.partners_users(user_id uuid,partner_id uuid);
CREATE TABLE public.channel_links(id uuid PRIMARY KEY,campaign_id uuid,channel_id uuid NOT NULL,archived_at timestamptz);
CREATE TABLE public.user_attribution(user_id uuid PRIMARY KEY,first_touch_link_id uuid,last_touch_link_id uuid);
CREATE TABLE public.catalog_fixture(unified_id text,title text,provider_name text,type text,location text,institution_id uuid,search_text text);
CREATE MATERIALIZED VIEW public.v_unified_opportunities AS SELECT * FROM public.catalog_fixture;
CREATE TABLE public.campus(id uuid,institution_id uuid);
CREATE TABLE public.courses(id uuid,campus_id uuid,course_name text);
CREATE TABLE public.opportunities(id uuid,course_id uuid,opportunity_type text,year integer,semester text);
CREATE TABLE cron.job(jobname text PRIMARY KEY,schedule text,command text);
CREATE FUNCTION cron.schedule(text,text,text) RETURNS bigint LANGUAGE plpgsql AS $$ BEGIN INSERT INTO cron.job VALUES ($1,$2,$3) ON CONFLICT(jobname) DO UPDATE SET schedule=$2,command=$3; RETURN 1; END $$;
CREATE FUNCTION get_tp2_partner_funnel(uuid DEFAULT NULL,integer DEFAULT NULL) RETURNS TABLE(partner_id uuid,partner_name text,total_unique_clicks bigint,total_applications_started bigint,total_applications_completed bigint,total_card_clicks bigint) LANGUAGE sql AS $$ SELECT NULL::uuid,NULL::text,0::bigint,0::bigint,0::bigint,0::bigint WHERE false $$;
CREATE VIEW vw_partner_funnel AS SELECT * FROM get_tp2_partner_funnel();
